  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum StaffRole {\n  ADMIN\n  KITCHEN\n  DISPATCH\n  DRIVER\n}\n\nmodel Staff {\n  id        String    @id @default(uuid())\n  email     String    @unique\n  password  String\n  role      StaffRole\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  // For driver role\n  deliveries        Order[]   @relation(\"DriverDeliveries\")\n  defaultForCompany Company[] @relation(\"DefaultDriver\")\n}\n\nmodel Company {\n  id                String   @id @default(uuid())\n  name              String\n  emailDomains      String[] // E.g. [\"test.com\", \"example.com\"]\n  deliveryAddresses String[]\n  billingContact    String\n\n  // Relations\n  ownerId   String?\n  owner     Employee?  @relation(\"CompanyOwner\", fields: [ownerId], references: [id])\n  employees Employee[] @relation(\"CompanyEmployees\")\n\n  // Price Tier\n  priceTierId String?\n  priceTier   PriceTier? @relation(fields: [priceTierId], references: [id])\n\n  // Delivery defaults\n  defaultDeliveryTime String? // e.g., \"12:30\"\n  deliveryMinutes     Int     @default(60) // Minutes before delivery order must leave kitchen\n  defaultPackaging    String?\n  driverInstructions  String?\n  defaultDriverId     String?\n  defaultDriver       Staff?  @relation(\"DefaultDriver\", fields: [defaultDriverId], references: [id])\n\n  // Hiding categories/items\n  hiddenCategoryIds String[]\n  hiddenDishIds     String[]\n\n  invoices Invoice[]\n}\n\nmodel Employee {\n  id        String @id @default(uuid())\n  email     String @unique\n  firstName String\n  lastName  String\n\n  companyId      String\n  company        Company   @relation(\"CompanyEmployees\", fields: [companyId], references: [id])\n  ownedCompanies Company[] @relation(\"CompanyOwner\")\n\n  // Permissions\n  canChooseAddress   Boolean @default(false)\n  canChangeTime      Boolean @default(false)\n  canChangePackaging Boolean @default(false)\n\n  // Preferences\n  allergens   String[]\n  dietaryTags String[]\n\n  orders Order[]\n}\n\nmodel PriceTier {\n  id        String  @id @default(uuid())\n  name      String  @unique\n  isDefault Boolean @default(false)\n\n  // Derived pricing formula could be stored as a string or json, e.g. { type: 'markup_percent', value: 15 }\n  derivedFrom String?\n\n  companies    Company[]\n  dishPrices   DishPrice[]\n  optionPrices OptionPrice[]\n}\n\nmodel Category {\n  id       String  @id @default(uuid())\n  name     String\n  order    Int\n  isActive Boolean @default(true)\n  isSecret Boolean @default(false)\n\n  dishes Dish[]\n}\n\nenum Temperature {\n  HOT\n  COLD\n}\n\nmodel Dish {\n  id               String      @id @default(uuid())\n  name             String\n  description      String?\n  image            String?\n  sku              String      @unique\n  temperature      Temperature\n  costPrice        Float\n  allergens        String[]\n  dietaryTags      String[]\n  kitchenStation   String?\n  minOrderQuantity Int         @default(1)\n  isActive         Boolean     @default(true)\n\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id])\n\n  optionGroups OptionGroup[]\n  prices       DishPrice[]\n  orderLines   OrderLine[]\n}\n\nmodel DishPrice {\n  id     String    @id @default(uuid())\n  dishId String\n  dish   Dish      @relation(fields: [dishId], references: [id])\n  tierId String\n  tier   PriceTier @relation(fields: [tierId], references: [id])\n  price  Float\n\n  @@unique([dishId, tierId])\n}\n\nmodel OptionGroup {\n  id           String  @id @default(uuid())\n  name         String // e.g. \"Choose your protein\"\n  isRequired   Boolean\n  displayOrder Int\n  dishId       String\n  dish         Dish    @relation(fields: [dishId], references: [id])\n\n  usesPortions Boolean @default(false) // If true, options have sizes\n\n  options Option[]\n}\n\nmodel Option {\n  id           String   @id @default(uuid())\n  name         String\n  cost         Float\n  allergens    String[]\n  dietaryTags  String[]\n  displayOrder Int\n\n  groupId String\n  group   OptionGroup @relation(fields: [groupId], references: [id])\n\n  prices   OptionPrice[]\n  portions Json? // e.g. [{ size: 'large', extraCharge: 2.00 }]\n}\n\nmodel OptionPrice {\n  id       String    @id @default(uuid())\n  optionId String\n  option   Option    @relation(fields: [optionId], references: [id])\n  tierId   String\n  tier     PriceTier @relation(fields: [tierId], references: [id])\n  price    Float\n\n  @@unique([optionId, tierId])\n}\n\nenum OrderStatus {\n  DRAFT\n  PLACED\n  CONFIRMED\n  DELIVERED\n  CANCELLED\n  REJECTED\n}\n\nmodel Order {\n  id         String   @id @default(uuid())\n  employeeId String\n  employee   Employee @relation(fields: [employeeId], references: [id])\n\n  deliveryDate    DateTime @db.Date\n  deliveryTime    String\n  deliveryAddress String\n  packaging       String\n\n  status OrderStatus @default(DRAFT)\n\n  // Totals\n  totalAmount Float\n\n  // Tracking\n  kitchenStartedAt DateTime?\n  kitchenReadyAt   DateTime?\n  dispatchReadyAt  DateTime?\n  outForDeliveryAt DateTime?\n  deliveredAt      DateTime?\n\n  driverId      String?\n  driver        Staff?   @relation(\"DriverDeliveries\", fields: [driverId], references: [id])\n  deliveryNote  String?\n  deliveryPhoto String?\n  isOnTime      Boolean?\n\n  invoiceId String?\n  invoice   Invoice? @relation(fields: [invoiceId], references: [id])\n\n  lines OrderLine[]\n}\n\nmodel OrderLine {\n  id      String @id @default(uuid())\n  orderId String\n  order   Order  @relation(fields: [orderId], references: [id])\n  dishId  String\n  dish    Dish   @relation(fields: [dishId], references: [id])\n\n  dishQuantity Int\n  dishPrice    Float // Recorded price at time of order\n\n  combinations Combination[]\n}\n\nmodel Combination {\n  id          String    @id @default(uuid())\n  orderLineId String\n  orderLine   OrderLine @relation(fields: [orderLineId], references: [id])\n\n  quantity   Int\n  totalPrice Float // Price of this specific combination * quantity\n\n  // Store the chosen options as JSON or a relational table. \n  // JSON is much easier for querying specific historical snapshots without complex joins.\n  chosenOptions Json // E.g. [{ optionId: \"...\", name: \"Paneer\", price: 1.50, size: \"regular\" }]\n\n  // Kitchen Prep State\n  kitchenStation String? // Copied from dish\n  isStarted      Boolean   @default(false)\n  isDone         Boolean   @default(false)\n  startedAt      DateTime?\n  doneAt         DateTime?\n}\n\nmodel Invoice {\n  id        String   @id @default(uuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id])\n  isPaid    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  orders Order[]\n}\n\nmodel Settings {\n  id                 String     @id @default(uuid()) // Single row table\n  kitchenWorkingDays Int[] // e.g. [1, 2, 3, 4, 5] for Mon-Fri\n  kitchenHolidays    DateTime[] @db.Date\n  cutoffDays         Int        @default(2)\n  cutoffTime         String     @default(\"16:00\")\n}\n",
